SELECT s1.`c0` AS `id`, s1.`c1` AS `city` FROM (SELECT s2.`c0` AS `c0`, s2.`c4` AS `c1` FROM (SELECT s3.`c0` AS `c0`, s3.`c1` AS `c1`, s3.`c2` AS `c2`, s4.`c0` AS `c3`, s4.`c1` AS `c4` FROM (SELECT `id` AS `c0`, `customer` AS `c1`, `amount` AS `c2` FROM `orders`) AS s3 INNER JOIN (SELECT `name` AS `c0`, `city` AS `c1` FROM `customers`) AS s4 ON (s3.`c1` = s4.`c0`)) AS s2) AS s1
